package com.multitenanterp.payroll;
import org.apache.pdfbox.Loader;import org.apache.pdfbox.rendering.PDFRenderer;import org.apache.pdfbox.text.PDFTextStripper;import org.junit.jupiter.api.Test;import javax.imageio.ImageIO;import java.math.BigDecimal;import java.nio.file.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PayslipPdfGeneratorTest{
 @Test void createsReadableBrandedPayslip()throws Exception{UUID id=UUID.randomUUID();byte[] pdf=new PayslipPdfGenerator().generate(new PayslipPdfGenerator.PayslipData(id,"Acme Services Private Limited","Bengaluru, Karnataka","EMP-1042","Asha Kumar",2026,9,new BigDecimal("30"),new BigDecimal("29.5"),new BigDecimal("75000"),new BigDecimal("8250"),new BigDecimal("66750"),List.of(new PayslipPdfGenerator.Item("Basic salary","EARNING",new BigDecimal("50000")),new PayslipPdfGenerator.Item("House rent allowance","EARNING",new BigDecimal("25000")),new PayslipPdfGenerator.Item("Provident fund","DEDUCTION",new BigDecimal("6000")),new PayslipPdfGenerator.Item("Income tax","DEDUCTION",new BigDecimal("2250")))));assertThat(pdf).startsWith(new byte[]{'%', 'P','D','F'});Path output=Path.of("target","pdf-qa","payslip-sample.pdf");Files.createDirectories(output.getParent());Files.write(output,pdf);try(var document=Loader.loadPDF(pdf)){String text=new PDFTextStripper().getText(document);assertThat(text).contains("PAYSLIP - SEPTEMBER 2026","Asha Kumar","NET PAY","66750.00",id.toString());ImageIO.write(new PDFRenderer(document).renderImageWithDPI(0,144),"PNG",Path.of("target","pdf-qa","payslip-sample.png").toFile());}}
}
